import{_ as a,o as t,c as o,a2 as r}from"./chunks/framework.hw3Av5Vn.js";const u=JSON.parse('{"title":"Rock","description":"","frontmatter":{},"headers":[],"relativePath":"demos/ROCK_MASHUP.md","filePath":"demos/ROCK_MASHUP.md"}'),n={name:"demos/ROCK_MASHUP.md"};function s(h,e,i,l,c,d){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="rock" tabindex="-1">Rock <a class="header-anchor" href="#rock" aria-label="Permalink to &quot;Rock&quot;">​</a></h1><p>The mashups that set another work&#39;s notes on a rock band. Each is described below, with the features it uses; <a href="./../DEMOS">About Demos</a> lists every demo.</p><ul><li><a href="#beach_flick">The Hungarian Dance No. 5 as Surf Rock</a>: <code>beach_flick.yml</code></li><li><a href="#magic_colored_smoke">The Caprice No. 24 as Psychedelic Rock</a>: <code>magic_colored_smoke.yml</code></li><li><a href="#moonlight_feedback">Clair de Lune as Shoegaze</a>: <code>moonlight_feedback.yml</code></li><li><a href="#night_on_synth_mountain">Night on Bald Mountain as Horror-Film Progressive Rock</a>: <code>night_on_synth_mountain.yml</code></li><li><a href="#three_chord_joy">The Ode to Joy as Punk Rock</a>: <code>three_chord_joy.yml</code></li><li><a href="#turkish_surf">The Rondo alla Turca as Surf Rock</a>: <code>turkish_surf.yml</code></li></ul><p><a id="beach_flick"></a></p><h2 id="the-hungarian-dance-no-5-as-surf-rock-beach-flick-yml" tabindex="-1">The Hungarian Dance No. 5 as Surf Rock: <code>beach_flick.yml</code> <a class="header-anchor" href="#the-hungarian-dance-no-5-as-surf-rock-beach-flick-yml" aria-label="Permalink to &quot;The Hungarian Dance No. 5 as Surf Rock: `beach_flick.yml`&quot;">​</a></h2><p>Beach flick: the Hungarian Dance No. 5 as sixties surf rock, after Misirlou (Dick Dale and His Del- Tones). The opening tune and its second strain from the Hungarian Dance No. 5 (Johannes Brahms, 1869) are public domain and are played from Claude&#39;s knowledge of the score, an octave down on the guitar&#39;s low strings; the tremolo picking is how the guitar plays them, and the riff with its flat second, the saxophone&#39;s answers, the solos and the tom-tom breaks are new, with nothing of the reference&#39;s own tune quoted.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/mashups/rock/beach_flick.yml" target="_blank" rel="noreferrer"><code>examples/mashups/rock/beach_flick.yml</code></a> · G minor · 160 BPM · 3:00 · 17 scenes · 12 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">ties</th></tr></thead><tbody><tr><td style="text-align:center;"><a href="./../PATTERNS#chords">✓</a></td><td style="text-align:center;"><a href="./../PATTERNS#ties">✓</a></td></tr></tbody></table><p><a id="magic_colored_smoke"></a></p><h2 id="the-caprice-no-24-as-psychedelic-rock-magic-colored-smoke-yml" tabindex="-1">The Caprice No. 24 as Psychedelic Rock: <code>magic_colored_smoke.yml</code> <a class="header-anchor" href="#the-caprice-no-24-as-psychedelic-rock-magic-colored-smoke-yml" aria-label="Permalink to &quot;The Caprice No. 24 as Psychedelic Rock: `magic_colored_smoke.yml`&quot;">​</a></h2><p>Magic colored smoke: the Caprice No. 24 as psychedelic blues-rock, after Purple Haze (The Jimi Hendrix Experience). The theme of the Caprice No. 24 for solo violin (Niccolò Paganini, about 1817) is public domain and is played as written, both halves, read from the corpus&#39;s score; the riff, the bass, the organ, the jam, the solos and the drums are new, with nothing of the reference&#39;s own tune quoted.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/mashups/rock/magic_colored_smoke.yml" target="_blank" rel="noreferrer"><code>examples/mashups/rock/magic_colored_smoke.yml</code></a> · A minor · 132 BPM · 3:00 · 14 scenes · 13 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">ties</th></tr></thead><tbody><tr><td style="text-align:center;"><a href="./../PATTERNS#chords">✓</a></td><td style="text-align:center;"><a href="./../PATTERNS#ties">✓</a></td></tr></tbody></table><p><a id="moonlight_feedback"></a></p><h2 id="clair-de-lune-as-shoegaze-moonlight-feedback-yml" tabindex="-1">Clair de Lune as Shoegaze: <code>moonlight_feedback.yml</code> <a class="header-anchor" href="#clair-de-lune-as-shoegaze-moonlight-feedback-yml" aria-label="Permalink to &quot;Clair de Lune as Shoegaze: `moonlight_feedback.yml`&quot;">​</a></h2><p>Moonlight feedback: Clair de Lune as early nineties shoegaze. The opening melody and the melody of the flowing middle of Clair de Lune from the Suite bergamasque (Claude Debussy, 1905) are public domain and are played as written, read from the Mutopia Project&#39;s edition, in their nine-eight time; the wall of strummed guitars, the answers, the bass and the drums are new.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/mashups/rock/moonlight_feedback.yml" target="_blank" rel="noreferrer"><code>examples/mashups/rock/moonlight_feedback.yml</code></a> · C# major · 90 BPM · 3:00 · 9 scenes · 9 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">ties</th></tr></thead><tbody><tr><td style="text-align:center;"><a href="./../PATTERNS#chords">✓</a></td><td style="text-align:center;"><a href="./../PATTERNS#ties">✓</a></td></tr></tbody></table><p><a id="night_on_synth_mountain"></a></p><h2 id="night-on-bald-mountain-as-horror-film-progressive-rock-night-on-synth-mountain-yml" tabindex="-1">Night on Bald Mountain as Horror-Film Progressive Rock: <code>night_on_synth_mountain.yml</code> <a class="header-anchor" href="#night-on-bald-mountain-as-horror-film-progressive-rock-night-on-synth-mountain-yml" aria-label="Permalink to &quot;Night on Bald Mountain as Horror-Film Progressive Rock: `night_on_synth_mountain.yml`&quot;">​</a></h2><p>Night On Synth Mountain: Night on Bald Mountain as the progressive rock of seventies Italian horror films. The creeping bass figure and the low brass theme of Night on Bald Mountain (Modest Mussorgsky, 1867, as Rimsky-Korsakov arranged it) are public domain and are played as written, read from the Mutopia Project&#39;s piano edition; the synthesizer bass, the bells&#39; arpeggios, the choir, the licks, the solos and the drums are new.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/mashups/rock/night_on_synth_mountain.yml" target="_blank" rel="noreferrer"><code>examples/mashups/rock/night_on_synth_mountain.yml</code></a> · D minor · 132 BPM · 2:58 · 16 scenes · 11 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">ties</th></tr></thead><tbody><tr><td style="text-align:center;"><a href="./../PATTERNS#chords">✓</a></td><td style="text-align:center;"><a href="./../PATTERNS#ties">✓</a></td></tr></tbody></table><p><a id="three_chord_joy"></a></p><h2 id="the-ode-to-joy-as-punk-rock-three-chord-joy-yml" tabindex="-1">The Ode to Joy as Punk Rock: <code>three_chord_joy.yml</code> <a class="header-anchor" href="#the-ode-to-joy-as-punk-rock-three-chord-joy-yml" aria-label="Permalink to &quot;The Ode to Joy as Punk Rock: `three_chord_joy.yml`&quot;">​</a></h2><p>Three chord joy: the Ode to Joy as seventies punk rock. The tune of the Ode to Joy from the Ninth Symphony (Ludwig van Beethoven, 1824) is public domain and is played as written, from Claude&#39;s knowledge of the score; the downstroked chords, the octave licks, the solos and the drums are new.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/mashups/rock/three_chord_joy.yml" target="_blank" rel="noreferrer"><code>examples/mashups/rock/three_chord_joy.yml</code></a> · D major · 190 BPM · 3:01 · 16 scenes · 9 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">ties</th></tr></thead><tbody><tr><td style="text-align:center;"><a href="./../PATTERNS#chords">✓</a></td><td style="text-align:center;"><a href="./../PATTERNS#ties">✓</a></td></tr></tbody></table><p><a id="turkish_surf"></a></p><h2 id="the-rondo-alla-turca-as-surf-rock-turkish-surf-yml" tabindex="-1">The Rondo alla Turca as Surf Rock: <code>turkish_surf.yml</code> <a class="header-anchor" href="#the-rondo-alla-turca-as-surf-rock-turkish-surf-yml" aria-label="Permalink to &quot;The Rondo alla Turca as Surf Rock: `turkish_surf.yml`&quot;">​</a></h2><p>Turkish surf: the Rondo alla Turca as sixties surf rock. The opening theme and the middle theme of the Rondo alla Turca from the Piano Sonata No. 11 (Wolfgang Amadeus Mozart, about 1783) are public domain and are played as written, an octave down on the guitar, from Claude&#39;s knowledge of the score; the runs with their flat seconds, the saxophone&#39;s answers, the solos and the drums are new.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/mashups/rock/turkish_surf.yml" target="_blank" rel="noreferrer"><code>examples/mashups/rock/turkish_surf.yml</code></a> · A minor · 150 BPM · 2:59 · 16 scenes · 12 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">ties</th></tr></thead><tbody><tr><td style="text-align:center;"><a href="./../PATTERNS#chords">✓</a></td><td style="text-align:center;"><a href="./../PATTERNS#ties">✓</a></td></tr></tbody></table>',33)])])}const p=a(n,[["render",s]]);export{u as __pageData,p as default};
